package com.greenocean.backend;
import com.greenocean.backend.professional.service.*;import com.greenocean.backend.common.exception.*;
import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.*;import org.springframework.transaction.annotation.Transactional;import org.junit.jupiter.api.*;import org.springframework.mock.web.MockMultipartFile;import java.util.*;import java.net.*;import java.io.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.clinic.commerce-enabled=true","greenocean.clinic.records-enabled=true","greenocean.clinic.record-keys=clinical-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.record-current-key=clinical-qa"}) @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseP3FilesTest extends PhaseP3Fixtures {
 static final ServerSocket scanner=server();static ServerSocket server(){try{var s=new ServerSocket(0,10,InetAddress.getLoopbackAddress());Thread.startVirtualThread(()->{while(!s.isClosed())try(var c=s.accept()){var in=new DataInputStream(c.getInputStream());while(in.readByte()!=0){}for(int n;(n=in.readInt())>0;)in.readNBytes(n);c.getOutputStream().write("stream: OK\0".getBytes(java.nio.charset.StandardCharsets.US_ASCII));}catch(IOException ignored){}});return s;}catch(IOException e){throw new IllegalStateException(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry p){p.add("greenocean.clinic.scanning-approved",()->true);p.add("greenocean.clinic.scanner-port",scanner::getLocalPort);}
 @AfterAll static void close()throws Exception{scanner.close();}
 MockMultipartFile file(){return new MockMultipartFile("file","private-synthetic.pdf","application/pdf","%PDF-1.4\nSynthetic private clinical attachment.\n%%EOF".getBytes());}
 @Test void scannedCiphertextDownloadsOnlyForPermittedRelationship(){UUID id=active(),file=files.upload(learner.id(),learner.session(),id,null,file());assertThat(files.download(learner.id(),learner.session(),id,file).bytes()).contains("Synthetic private clinical attachment".getBytes());assertThatThrownBy(()->files.download(issuer.id(),issuer.session(),id,file)).isInstanceOf(ForbiddenException.class);assertThat(new String(db.queryForObject("SELECT body_cipher FROM clinic_attachments WHERE id=?",byte[].class,file),java.nio.charset.StandardCharsets.UTF_8)).doesNotContain("Synthetic private clinical attachment");}
 @Test void attachmentCorrectionCreatesLinkedVersionRatherThanOverwriting(){UUID id=active(),first=files.upload(learner.id(),learner.session(),id,null,file()),next=files.upload(learner.id(),learner.session(),id,first,file());assertThat(next).isNotEqualTo(first);assertThat(db.queryForObject("SELECT previous_id FROM clinic_attachments WHERE id=?",UUID.class,next)).isEqualTo(first);assertThat(files.list(learner.id(),learner.session(),id)).hasSize(2);}
 @Test void matchingSignatureAndBoundedSizeAreRequired(){UUID id=active();assertThatThrownBy(()->files.upload(learner.id(),learner.session(),id,null,new MockMultipartFile("file","disguised.pdf","application/pdf","this is not a PDF".getBytes()))).isInstanceOf(IllegalArgumentException.class);}
}
